/**
 * Bundled city data for the map artifact.
 *
 * Generated by `scripts/build-cities.mjs` from GeoNames data
 * (https://www.geonames.org/, CC BY 4.0) — see `MAP_DATA_ATTRIBUTION`. Committed
 * rather than fetched, so the map still renders with no network.
 *
 * Two tiers, mirroring the atlas levels in `map-atlas.ts`:
 *
 *   major   pop >= 200k    2,181 cities    79 kB   world and continental views
 *   detail  pop >=  30k   14,096 cities   502 kB   regional views and tighter
 */

import type { GeoProjection } from 'd3-geo';
import { MAP_H, MAP_W } from './map-geo';

/** `[name, lat, lng, populationThousands, countryCode]` — tuples, because keys would dominate. */
type CityRow = [string, number, number, number, string];

export type City = {
  name: string;
  lat: number;
  lng: number;
  /** Thousands of inhabitants, as generated. */
  population: number;
  country: string;
};

export type CityDetail = 'major' | 'detail';

export const MAP_DATA_ATTRIBUTION = 'Natural Earth · GeoNames (CC BY 4.0)';

const cache = new Map<CityDetail, Promise<City[]>>();

/** Matches `detailForZoom` in map-atlas so the two datasets always agree. */
export function cityDetailForZoom(zoom: number): CityDetail {
  return zoom >= 5 ? 'detail' : 'major';
}

async function importRows(detail: CityDetail): Promise<CityRow[]> {
  const loaded =
    detail === 'detail'
      ? await import('../data/cities-detail.json')
      : await import('../data/cities-major.json');
  return ((loaded as { default?: unknown }).default ?? loaded) as CityRow[];
}

export function loadCities(detail: CityDetail): Promise<City[]> {
  const cached = cache.get(detail);
  if (cached) return cached;

  const pending = importRows(detail).then((rows) =>
    rows.map(([name, lat, lng, population, country]) => ({ name, lat, lng, population, country }))
  );

  cache.set(detail, pending);
  // A failed import must not poison the cache — the next map should retry.
  pending.catch(() => cache.delete(detail));
  return pending;
}

export type ProjectedCity = City & { x: number; y: number };

/**
 * Cities that fall inside the drawing surface, largest first.
 *
 * The generated files are sorted by descending population, so taking the first
 * `limit` hits keeps the most significant places without a sort at render time. Note
 * the early exit only helps a wide view; a tight one genuinely scans every row,
 * because almost none of them are on screen.
 */
export function citiesInView(
  cities: City[],
  projection: GeoProjection,
  options: { limit?: number; width?: number; height?: number; margin?: number } = {}
): ProjectedCity[] {
  /*
   * 24, not 60. Collision avoidance alone will happily place ~60 non-overlapping names
   * across a continental view, which measured at ~10% label ink and read as clutter.
   * Because the generated data is sorted by descending population, capping the count
   * keeps the most significant places and drops the rest.
   */
  const limit = options.limit ?? 24;
  const width = options.width ?? MAP_W;
  const height = options.height ?? MAP_H;
  const margin = options.margin ?? 6;
  const found: ProjectedCity[] = [];

  for (const city of cities) {
    const xy = projection([city.lng, city.lat]);
    if (!xy || !Number.isFinite(xy[0]) || !Number.isFinite(xy[1])) continue;
    const [x, y] = xy;
    if (x < margin || y < margin || x > width - margin || y > height - margin) continue;
    found.push({ ...city, x, y });
    if (found.length >= limit) break;
  }

  return found;
}

export function formatPopulation(thousands: number): string {
  if (thousands >= 1000) return `${(thousands / 1000).toFixed(1)}M`;
  return `${thousands}k`;
}
